// Mock Point_2 for testing
struct Point_2 {
    double x, y;
    Point_2() : x(0), y(0) {}
    Point_2(double x, double y) : x(x), y(y) {}
    double& operator[](int i) { return i == 0 ? x : y; }
    const double& operator[](int i) const { return i == 0 ? x : y; }
};

std::vector<Point_2> convex_hull_graham(std::vector<Point_2> points) {
    // Handle edge cases
    if (points.size() <= 1) return points;

    // Find the point with lowest y (and lowest x if tie) - pivot
    size_t pivot_idx = 0;
    for (size_t i = 1; i < points.size(); i++) {
        if (points[i].y < points[pivot_idx].y || 
            (points[i].y == points[pivot_idx].y && points[i].x < points[pivot_idx].x)) {
            pivot_idx = i;
        }
    }
    std::swap(points[0], points[pivot_idx]);
    Point_2 pivot = points[0];

    // Sort points by polar angle with pivot (break ties by distance)
    std::sort(points.begin() + 1, points.end(), [&](const Point_2& a, const Point_2& b) {
        double cross = (a.x - pivot.x)*(b.y - pivot.y) - (a.y - pivot.y)*(b.x - pivot.x);
        if (std::abs(cross) > 1e-12) return cross > 0;
        // If collinear, closer points come first
        double da = (a.x - pivot.x)*(a.x - pivot.x) + (a.y - pivot.y)*(a.y - pivot.y);
        double db = (b.x - pivot.x)*(b.x - pivot.x) + (b.y - pivot.y)*(b.y - pivot.y);
        return da < db;
    });

    // Remove duplicate angles (keep farthest)
    size_t m = 1;
    for (size_t i = 2; i < points.size(); i++) {
        double cross = (points[i].x - pivot.x)*(points[m].y - pivot.y) - 
                       (points[i].y - pivot.y)*(points[m].x - pivot.x);
        if (std::abs(cross) > 1e-12) {
            points[++m] = points[i];
        } else {
            // Same angle, keep the farthest
            double dm = (points[m].x - pivot.x)*(points[m].x - pivot.x) + 
                        (points[m].y - pivot.y)*(points[m].y - pivot.y);
            double di = (points[i].x - pivot.x)*(points[i].x - pivot.x) + 
                        (points[i].y - pivot.y)*(points[i].y - pivot.y);
            if (di > dm) points[m] = points[i];
        }
    }
    points.resize(m + 1);

    // Graham scan
    std::vector<Point_2> hull;
    hull.reserve(points.size());
    for (const auto& p : points) {
        while (hull.size() >= 2) {
            const Point_2& a = hull[hull.size()-2];
            const Point_2& b = hull[hull.size()-1];
            double cross = (b.x - a.x)*(p.y - a.y) - (b.y - a.y)*(p.x - a.x);
            if (cross <= 1e-12) hull.pop_back();
            else break;
        }
        hull.push_back(p);
    }

    return hull;
}

