            double dm = (points[m].x() - pivot.x())*(points[m].x() - pivot.x()) + 
                        (points[m].y() - pivot.y())*(points[m].y() - pivot.y());
            double di = (points[i].x() - pivot.x())*(points[i].x() - pivot.x()) + 
                        (points[i].y() - pivot.y())*(points[i].y() - pivot.y());
            if (di > dm) points[m] = points[i];
        }
    }
    points.resize(m + 1);

    // Graham scan
    std::vector<Point_2> hull;
    hull.reserve(points.size());
    for (const auto& p : points) {
        while (hull.size() >= 2) {
            const Point_2& a = hull[hull.size()-2];
            const Point_2& b = hull[hull.size()-1];
            double cross = (b.x() - a.x())*(p.y() - a.y()) - (b.y() - a.y())*(p.x() - a.x());
            if (cross <= 0) hull.pop_back();
            else break;
        }
        hull.push_back(p);
    }

    return hull;
